-- Update the untouched initial privacy draft; preserve administrator edits and all published snapshots.
-- Existing custom drafts retain their contents and receive a clearly labelled current-version supplement.
UPDATE legal_document
SET draft_json = CASE
        WHEN lock_version = 0 AND published_revision = 1 THEN CONVERT( USING utf8mb4)
        ELSE JSON_ARRAY_APPEND(draft_json, '$.sections', CAST(CONVERT( USING utf8mb4) AS JSON))
    END,
    requires_reconsent = TRUE,
    lock_version = lock_version + 1
WHERE document_key = 'privacy';
